import*as THREE from'three';import{Component,Port,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{Antenna}from'./Antenna.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;const hole=(s,x,y,r)=>{const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);};
const solid=(p,s,d,v,m,n)=>mesh(p,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:64}),m,v,n);
function annulus(p,outer,inner,depth,pos,mat,name){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);hole(s,0,0,inner);return solid(p,s,depth,pos,mat,name);}
function electronics(host){
 const s=new THREE.Shape();s.moveTo(-10.2,21.5);s.lineTo(10.2,21.5);s.lineTo(10.2,-16.6);s.lineTo(8,-16.6);s.absarc(8,-20,3.4,Math.PI/2,Math.PI*1.5,false);s.lineTo(10.2,-23.4);s.lineTo(10.2,-29);s.lineTo(5.7,-29);s.lineTo(5.7,-24.8);s.lineTo(-5.7,-24.8);s.lineTo(-5.7,-29);s.lineTo(-10.2,-29);s.lineTo(-10.2,-23.4);s.lineTo(-8,-23.4);s.absarc(-8,-20,3.4,Math.PI*1.5,Math.PI*2.5,false);s.lineTo(-10.2,-16.6);s.closePath();hole(s,0,-20,1.8);
 const green=materials.plastic(0x205b3c,{roughness:.91}),gold=materials.metal(0xc8b373,{roughness:.55}),metal=materials.metal(0xb8bbae,{roughness:.45}),dark=materials.plastic(0x202621,{roughness:.86});
 const pcb=solid(host.body,s,.8,[0,0,-1.65],green,'GPS SMA fixed carrier PCB with real mounting and Grove reliefs');pcb.userData={role:'physical-pcb',inferred:true};
 const substrate=slab(host.body,10.1,9.7,.65,.14,[0,7,-.85],green,[],.02);substrate.name='GPS SMA ATGM336H physical module substrate';
 const shield=slab(host.body,9.7,9.3,2,.4,[0,7,-.2],materials.metal(0xb8b9a3,{roughness:.7}),[],.06);shield.name='GPS SMA ATGM336H opaque GNSS module shielding can';shield.userData={role:'physical-shield',part:'ATGM336H',inferred:true};
 const terminals=[];for(const sign of[-1,1])for(let i=0;i<9;i++){terminals.push(mesh(host.body,new THREE.BoxGeometry(.6,.62,.3),gold,[sign*5.05,7+(i-4)*1.0,-.2],'GPS SMA ATGM336H physical castellation'));mesh(host.body,new THREE.BoxGeometry(.45,.62,.14),metal,[sign*5.3,7+(i-4)*1.,-.8],'GPS SMA module solder fillet');}
 const lna=slab(host.body,1.6,1.6,.6,.09,[7.2,13.6,-.85],dark,[],.01);lna.name='GPS SMA U2 MAX2659 physical low-noise-amplifier package';
 const cell=mesh(host.body,new THREE.CylinderGeometry(3.25,3.25,1.6,64).rotateX(Math.PI/2),metal,[-3.2,-5,-.45],'GPS SMA BT1 physical backup cell');mesh(host.body,new THREE.BoxGeometry(1.25,7,.15),gold,[-3.2,-5,.42],'GPS SMA retained backup-cell metal tab');
 const led=slab(host.body,1.6,.8,.6,.06,[6.6,4,-.85],materials.plastic(0xced8ca,{roughness:.7}),[],.01);led.name='GPS SMA hidden non-emissive LED1 physical package behind opaque cover';
 const regulator=slab(host.body,2.8,2.8,.8,.1,[4,-6,-.85],dark,[],.01);regulator.name='GPS SMA U1 physical3V3 regulator';
 const passives=[];for(const[x,y]of[[-7,8],[-7,11],[-6,17],[-3,17],[0,17],[4,17],[7,9],[7,6],[-7,-6],[7,-6],[7,-10],[4,-10],[-3,-11]]){const c=slab(host.body,1.6,.8,.65,.07,[x,y,-.85],materials.plastic(0xa99a73,{roughness:.86}),[],.01);c.name='GPS SMA fixed resistor or capacitor package';passives.push(c);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.3,.82,.65),metal,[x+sign*.7,y,-.525],'GPS SMA passive physical solder termination');}
 return{pcb,substrate,shield,terminals,lna,cell,led,regulator,passives};
}
function sma(host){
 const g=new THREE.Group();g.name='GPS SMA true SMA female connector';g.position.fromArray(spec.sma.position);g.quaternion.copy(FACE.top);host.body.add(g);const gold=materials.metal(0xd1b85c,{roughness:.36}),white=materials.plastic(0xdcd9ba,{roughness:.75}),dark=materials.plastic(0x252b22,{roughness:.8});
 const barrel=annulus(g,2.78,2.1,10.3,[0,0,-10.3],gold,'GPS SMA SMA continuous annular female outer barrel');
 const lip=annulus(g,2.78,2.1,.45,[0,0,-.45],gold,'GPS SMA SMA open annular mating lip');
 class ThreadCurve extends THREE.Curve{getPoint(t,target=new THREE.Vector3()){const a=t*tau*9;return target.set(Math.cos(a)*2.94,Math.sin(a)*2.94,-7.2+t*6.3);}}
 const thread=mesh(g,new THREE.TubeGeometry(new ThreadCurve(),648,.16,8,false),gold,[0,0,0],'GPS SMA SMA real continuous helical external thread');
 const hex=new THREE.Shape();for(let i=0;i<6;i++){const a=tau*i/6+Math.PI/6;const x=Math.cos(a)*3.13,y=Math.sin(a)*3.13;i?hex.lineTo(x,y):hex.moveTo(x,y);}hex.closePath();hole(hex,0,0,1.05);const nut=solid(g,hex,4,[0,0,-13.4],gold,'GPS SMA SMA retained internal hex body visible through both native windows');
 const dielectric=annulus(g,2.095,.6,4.35,[0,0,-4.55],white,'GPS SMA SMA recessed PTFE insulator with genuine centre bore');
 const contact=annulus(g,.58,.25,4,[0,0,-4.4],gold,'GPS SMA SMA female hollow recessed centre contact sleeve');
 const stop=mesh(g,new THREE.CylinderGeometry(.25,.25,.12,32).rotateX(Math.PI/2),gold,[0,0,-4.56],'GPS SMA SMA recessed centre contact blind end');
 const shoulder=annulus(g,1.04,.55,1.2,[0,0,-14.4],white,'GPS SMA SMA rear feed-through dielectric');const rearPin=mesh(g,new THREE.CylinderGeometry(.24,.24,1.6,24).rotateX(Math.PI/2),gold,[0,0,-14.4],'GPS SMA SMA rear centre terminal');
 const rear=annulus(g,1.45,.62,1.2,[0,0,-15],gold,'GPS SMA SMA rear coax termination sleeve');
 const cablePath=new THREE.CatmullRomCurve3([new THREE.Vector3(0,24.3,0),new THREE.Vector3(0,22.2,.1),new THREE.Vector3(5.5,20,.4),new THREE.Vector3(8,15.8,.3),new THREE.Vector3(7.5,10.5,.05)]);const coax=mesh(host.body,new THREE.TubeGeometry(cablePath,48,.5,10,false),materials.plastic(0x171e1a,{roughness:.86}),[0,0,0],'GPS SMA concealed actual SMA to IPEX coax');
 const ipg=new THREE.Group();ipg.name='GPS SMA fixed IPEX board antenna receptacle';ipg.position.set(7.5,10.5,-.25);host.body.add(ipg);const socket=annulus(ipg,1.1,.55,.6,[0,0,0],gold,'GPS SMA actual annular IPEX socket');mesh(ipg,new THREE.CylinderGeometry(.23,.23,.5,20).rotateX(Math.PI/2),gold,[0,0,.25],'GPS SMA IPEX central terminal');
 const port=host.add(new Port({id:'sma',label:'SMA female · antenna connector',connector:'sma-female',position:spec.sma.position,quaternion:portQuaternion('top'),hitSize:[6.2,1,6.2],pins:[{n:1,name:'centre ANT'},{n:2,name:'outer shield'}],meta:{role:'visual-connector',face:'top',signalRole:'antenna',scope:'Female connector shape, external thread, real recessed centre socket, pose and matching connector type only; no RF field,GNSS,NMEA,frequency,signal,positioning,power or electrical simulation'}}));return{group:g,barrel,lip,thread,nut,dielectric,contact,stop,shoulder,rearPin,rear,coax,ipex:ipg,socket,port};
}
function grove(host){const g=new THREE.Group();g.name='GPS SMA open red HY2.0-4P socket';g.position.fromArray(spec.grove.position);g.quaternion.copy(FACE.bottom);host.body.add(g);const plastic=materials.plastic(spec.grove.color,{roughness:.66}),metal=materials.metal(0xc0b797,{roughness:.42}),box=(s,p,n,m=plastic)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'GPS SMA Grove '+n),depth=6.6;
 for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.9],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'rear wall');box([4.8,.45,2.3],[0,2.375,-4.6],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.7],[(i-1.5)*2,.2,-3.7],`contact ${i+1}`,metal));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-6],`solder tail ${i+1}`,metal);}
 const port=host.add(new Port({id:'grove',label:'PORT.C · UART',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'RXD',color:'yellow'},{n:4,name:'TXD',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Physical attachment, four contacts, pin labels and cable pose only; no UART transaction,GNSS,NMEA,RF,position,signal,supply or electrical behavior'}}));return{group:g,contacts,port};}
export function buildGPSSMA(host,{antenna=host.options.antenna??false,antennaPoints=host.options.antennaPoints}={}){
 if(typeof antenna!=='boolean')throw new TypeError('antenna must be true or false');
 const parts=addCadParts(host,data,{shell:materials.plastic(0x555956,{roughness:.85})}),board=electronics(host),output=sma(host),input=grove(host),fixings=[];
 for(const[x,y]of[[0,-20],[-8.2,27.4],[8.2,27.4]]){fixings.push(screw(host.body,[x,y,-3.97],'back',1.35));mesh(host.body,new THREE.CylinderGeometry(.6,.6,1.8,24).rotateX(Math.PI/2),materials.metal(0xa1a797),[x,y,-2.7],'GPS SMA concealed fixed shell retaining shank');}
 const anchor=host.add(new Component({id:'sensor',label:'ATGM336H passive appearance anchor',position:[0,7,1.5],meta:{role:'visual-anchor',scope:'Passive physical anchor only;no GNSS,location,satellites,RF field,gain,NMEA,clock,PPS,UART,sensor values,voltage,firmware or electrical commands'}}));
 host.gpsSmaAssembly={parts,board,output,input,fixings,anchor};host.unitStickers=addStickers(host);
 if(antenna)output.port.attach(new Antenna({points:antennaPoints,artwork:host.options.artwork}));
}
